<?php
namespace App\Http\Requests\Testimonials; use App\Domain\PublicChrome\{PublicAssetPath,PublicLink}; use App\Models\Client; use Closure; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule; class SaveTestimonialRequest extends FormRequest { public function authorize():bool{return $this->user()!==null;} protected function prepareForValidation():void{$this->merge(['is_featured'=>$this->boolean('is_featured'),'rating'=>$this->filled('rating')?$this->integer('rating'):null]);} public function rules():array{$asset=fn(string $a,mixed $v,Closure $fail)=>PublicAssetPath::isSafe(is_string($v)?$v:null)?:$fail('Use an approved local raster image path.');$url=fn(string $a,mixed $v,Closure $fail)=>$v&&!PublicLink::isSafeUrl((string)$v)?$fail('Use a safe HTTP/HTTPS URL without credentials.'):null;return ['client_id'=>['nullable',Rule::exists(Client::class,'id')->whereNull('archived_at')],'person_name'=>['required','string','max:160'],'designation'=>['nullable','string','max:160'],'organization_name'=>['nullable','string','max:160'],'quote'=>['required','string','max:3000'],'image_path'=>['nullable','string','max:255',$asset],'image_alt'=>['nullable','required_with:image_path','string','max:180'],'rating'=>['nullable','integer','between:1,5'],'source_url'=>['nullable','string','max:2048',$url],'is_featured'=>['boolean']];} }
